<?php if (($paginationTotalPages ?? 1) > 1): ?><nav class="pagination" aria-label="<?= htmlspecialchars((string) ($paginationLabel ?? 'Result pages'), ENT_QUOTES, 'UTF-8') ?>"><?php for ($paginationPage = 1; $paginationPage <= $paginationTotalPages; $paginationPage++): ?><a href="<?= htmlspecialchars((string) call_user_func($paginationUrl, $paginationPage), ENT_QUOTES, 'UTF-8') ?>" <?= $paginationPage === ($paginationCurrentPage ?? 1) ? 'aria-current="page"' : '' ?>><?= $paginationPage ?></a><?php endfor; ?></nav><?php endif; ?>
